import sys
import importlib.abc
import importlib.machinery

class MaliciousLoader(importlib.abc.Loader):
    def __init__(self, module_name, original_spec):
        self.module_name = module_name
        self.original_spec = original_spec

    def create_module(self, spec):
        return None

    def exec_module(self, module):
        if self.module_name == 'traceback':
            self._corrupt_traceback(module)
        elif self.module_name == 'linecache':
            self._corrupt_linecache(module)

    def _corrupt_traceback(self, module):
        import sys as _sys
        original_module = self.original_spec.loader.load_module(self.module_name)

        for attr in dir(original_module):
            if not hasattr(module, attr):
                setattr(module, attr, getattr(original_module, attr))

        original_format_exception = original_module.format_exception
        original_format_exception_only = original_module.format_exception_only
        original_print_exception = original_module.print_exception
        original_format_tb = original_module.format_tb

        def broken_format_exception(exc, /, value=None, tb=None, limit=None, chain=True):
            try:
                if value is None and tb is None:
                    lines = original_format_exception(exc, value, tb, limit, chain)
                else:
                    lines = original_format_exception(exc, value, tb, limit, chain)
                corrupted = []
                for i, line in enumerate(lines):
                    if i % 3 == 0:
                        corrupted.append(line[:len(line)//2] + '\n')
                    elif i % 3 == 1:
                        corrupted.append(''\'.join(reversed(line[:20])) + '\n')
                    else:
                        if len(corrupted) > 1:
                            corrupted.pop()
                return corrupted
            except:
                raise RuntimeError("Traceback formatting corrupted")

        def broken_format_exception_only(exc, /, value=None):
            if value is None:
                lines = original_format_exception_only(exc)
            else:
                lines = original_format_exception_only(exc, value)
            if lines:
                return [lines[0][:10] + "...CORRUPTED...\n"]
            return []

        def broken_print_exception(exc, /, value=None, tb=None, limit=None, file=None, chain=True):
            import io
            raise AttributeError("print_exception has been corrupted")

        def broken_format_tb(tb, limit=None):
            lines = original_format_tb(tb, limit)
            corrupted = []
            for line in lines:
                if len(line) > 10:
                    corrupted.append("")
            return corrupted

        module.format_exception = broken_format_exception
        module.format_exception_only = broken_format_exception_only
        module.print_exception = broken_print_exception
        module.format_tb = broken_format_tb

    def _corrupt_linecache(self, module):
        original_module = self.original_spec.loader.load_module(self.module_name)

        for attr in dir(original_module):
            if not hasattr(module, attr):
                setattr(module, attr, getattr(original_module, attr))

        original_getline = original_module.getline
        original_getlines = original_module.getlines

        def broken_getline(filename, lineno, module_globals=None):
            import random
            line = original_getline(filename, lineno, module_globals)
            if line and random.random() > 0.5:
                return ""
            elif line:
                return ''\'.join(reversed(line[:min(15, len(line))])) + '\n'
            return line

        def broken_getlines(filename, module_globals=None):
            lines = original_getlines(filename, module_globals)
            return ["" for _ in lines]

        module.getline = broken_getline
        module.getlines = broken_getlines

class MaliciousFinder(importlib.abc.MetaPathFinder):
    def find_spec(self, fullname, path, target=None):
        if fullname in ('traceback', 'linecache'):
            for finder in sys.meta_path[1:]:
                if hasattr(finder, 'find_spec'):
                    original_spec = finder.find_spec(fullname, path, target)
                    if original_spec and original_spec.loader:
                        new_spec = importlib.machinery.ModuleSpec(
                            fullname,
                            MaliciousLoader(fullname, original_spec),
                            origin=original_spec.origin
                        )
                        return new_spec
        return None

if not any(isinstance(finder, MaliciousFinder) for finder in sys.meta_path):
    sys.meta_path.insert(0, MaliciousFinder())
